// ============================================
// Nodo: JSON_to_Globals  (v3)
// Riceve msg.payload = config JSON (oggetto o stringa)
// Registra tutte le variabili globali usate dai nodi
// XOR_validation e Packet_Decoder.
// ============================================

let config = msg.payload;
if (typeof config === "string") {
    try { config = JSON.parse(config); }
    catch(e) { node.error("JSON non valido: " + e.message); return null; }
}
if (!config || typeof config !== "object") {
    node.error("msg.payload non è un oggetto di configurazione valido");
    return null;
}

// ── 1. Costanti protocollo ────────────────────────────────────────────────────
global.set("PKT_MAGIC",       config.PROTO.MAGIC);
global.set("PKT_VERSION",     config.PROTO.VERSION);
global.set("HEADER_SIZE",     config.PROTO.HEADER_SIZE);
global.set("PACKET_MIN_SIZE", config.PROTO.MIN_SIZE);

// ── 2. Scaling factors ────────────────────────────────────────────────────────
global.set("ENC_TEMP_FACTOR",  config.SCALING.TEMP_FACTOR);
global.set("ENC_TEMP_OFFSET",  config.SCALING.TEMP_OFFSET);
global.set("ENC_HUM_FACTOR",   config.SCALING.HUM_FACTOR);
global.set("ENC_PRESS_FACTOR", config.SCALING.PRESS_FACTOR);

// ── 3. Packet types + mappa inversa ──────────────────────────────────────────
const typeMap = {};
for (const [key, value] of Object.entries(config.TYPES)) {
    global.set(`TYPE_${key}`, value);
    typeMap[value] = key;
}
global.set("TYPE_NAME_MAP", typeMap);

// ── 4. Device IDs + mappa inversa ────────────────────────────────────────────
const deviceMap = {};
for (const [key, value] of Object.entries(config.DEVICES)) {
    global.set(`DEVICE_${key}`, value);
    deviceMap[value] = key;
}
global.set("DEVICE_NAME_MAP", deviceMap);

// ── 5. Enumerazioni opzionali ─────────────────────────────────────────────────
if (config.COMMANDS)       global.set("COMMANDS",       config.COMMANDS);
if (config.TENDE_COMMANDS) global.set("TENDE_COMMANDS", config.TENDE_COMMANDS);
if (config.ACK_STATES)     global.set("ACK_STATES",     config.ACK_STATES);

// ── 6. Parser specs (intero oggetto) ─────────────────────────────────────────
// Il Packet_Decoder legge PARSER_SPECS direttamente.
// Ogni spec può avere formato:
//   { name: "...", fields: [...] }   ← nuovo formato con metadati
//   [...]                            ← vecchio formato array diretto
global.set("PARSER_SPECS", config.PARSER_SPECS);

// Espone anche le singole spec come globali separate (comodo per debug)
for (const [typeName, spec] of Object.entries(config.PARSER_SPECS)) {
    global.set(`PARSER_SPEC_${typeName}`, spec);
}

// ── 7. Report ─────────────────────────────────────────────────────────────────
const specCount   = Object.keys(config.PARSER_SPECS).length;
const deviceCount = Object.keys(config.DEVICES).length;
const typeCount   = Object.keys(config.TYPES).length;

node.log(`✅ Globals caricati: proto=v${config.PROTO.VERSION} | tipi=${typeCount} | devices=${deviceCount} | specs=${specCount}`);
node.status({ fill: "green", shape: "dot", text: `OK – ${specCount} specs, ${deviceCount} devices` });

msg.payload = {
    status:  "ok",
    specs:   Object.keys(config.PARSER_SPECS),
    devices: Object.keys(config.DEVICES)
};
return msg;
